async function witnessSelfTest(trust, signer) {
  const result = { tsa: false, packet: false, signature: false };
  try {
    const stamp = verifyTimeStampToken(
      extractToken(Buffer.from(DIGICERT_PROBE_TSR, "base64")),
      { sha256Digest: Buffer.from(DIGICERT_PROBE.sha256Digest, "hex"), nonce: BigInt(DIGICERT_PROBE.nonce) },
      trust
    );
    result.tsa = stamp.genTime === "20261115023745Z" && stamp.nonce === DIGICERT_PROBE.nonce;
  } catch {
    result.tsa = false;
  }
  try {
    const t = "2026-11-15T02:37:45.000000Z";
    const packet = {
      version: PACKET_VERSION,
      binding: {
        claimId: "self-test",
        policyId: "pregame-native-v1",
        codeVersion: "0".repeat(40),
        gameId: 1,
        slateDate: "2026-11-14",
        homeTeamId: 1,
        awayTeamId: 2,
        homeAbbrev: "AAA",
        awayAbbrev: "BBB",
        scheduledStart: t,
        calendarRevision: "0".repeat(64),
        inputCutoff: t
      },
      readWindow: { start: t, end: t },
      statedCutoff: "2026-11-15T02:37:50.000000Z",
      seasonBootstrapApplied: false,
      modelEnvironment: { "z": "1", "a": null },
      candidates: { skaters: [3, 1, 2], goalies: [], reserves: [] },
      transport: { calls: 1, httpCalls: 1, rows: 1, bytes: 1, stampToleranceMs: 5e3 },
      reads: [{ receivedAt: t, note: "é ✓ \0-free", nested: { b: 2, a: 1 } }]
    };
    const encoded = encodePacket(packet);
    const decoded = decodePacket(Uint8Array.from(encoded.bytes));
    result.packet = decoded.rawSha256 === encoded.rawSha256 && decoded.canonicalSha256 === encoded.canonicalSha256 && decoded.rawSha256 === createHash5("sha256").update(Uint8Array.from(encoded.bytes)).digest("hex");
  } catch {
    result.packet = false;
  }
  try {
    const text = "forge-witness-self-test";
    const signature = Uint8Array.from(atob(await signer.sign(text)), (c) => c.charCodeAt(0));
    const key = await globalThis.crypto.subtle.importKey("jwk", { kty: "OKP", crv: "Ed25519", x: signer.publicKey }, { name: "Ed25519" }, false, ["verify"]);
    const ok = await globalThis.crypto.subtle.verify({ name: "Ed25519" }, key, signature, new TextEncoder().encode(text));
    const forged = await globalThis.crypto.subtle.verify({ name: "Ed25519" }, key, signature, new TextEncoder().encode(text + "!"));
    result.signature = ok && !forged;
  } catch {
    result.signature = false;
  }
  return result;
}

